const response = $input.first().json;
const points = response.result?.points || [];
const weekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;

let totalOps = 0, errors = 0, stores = 0, recalls = 0;
const projects = new Set();

for (const p of points) {
  const payload = p.payload || {};
  const ts = new Date(payload.timestamp || 0).getTime();
  if (ts < weekAgo) continue;

  totalOps++;
  const action = payload.action || '';
  if (payload.error) errors++;
  if (action.includes('store') || action.includes('MEMORY_STORED')) stores++;
  if (action.includes('recall') || action.includes('MEMORY_RECALLED')) recalls++;
  if (payload.project) projects.add(payload.project);
}

const errorRate = totalOps > 0 ? (errors / totalOps * 100).toFixed(2) : 0;

return [{ json: {
  week_ending: new Date().toISOString().split('T')[0],
  total_operations: totalOps,
  stores: stores,
  recalls: recalls,
  errors: errors,
  error_rate_pct: parseFloat(errorRate),
  active_projects: Array.from(projects),
  project_count: projects.size
}}];

const embedding = $json.embedding;
const metrics = $('Compute Weekly Metrics').first().json;
if (!embedding) return { json: { error: 'no embedding' } };

const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

return {
  json: {
    point: {
      id: uuid,
      vector: embedding,
      payload: {
        benchmark_type: 'weekly_system_health',
        week_ending: metrics.week_ending,
        metrics: {
          total_operations: metrics.total_operations,
          stores: metrics.stores,
          recalls: metrics.recalls,
          errors: metrics.errors,
          error_rate_pct: metrics.error_rate_pct,
          project_count: metrics.project_count
        },
        active_projects: metrics.active_projects,
        created_at: new Date().toISOString(),
        source: 'auto_weekly_benchmark'
      }
    }
  }
};
